fn main() {
    // ---- Stack: fast, fixed size, LIFO ----
    // Data on the stack:
    let x: i32 = 5;           // i32 is 4 bytes, on the stack
    let y: bool = true;        // bool is 1 byte, on the stack
    let z: char = 'a';         // char is 4 bytes, on the stack
    let tuple = (1, 2, 3);     // Tuple of i32s, on the stack

    // ---- Heap: slower, variable size, flexible ----
    // Data on the heap:
    let s = String::from("hello");  // String points to heap data
    // The String itself is on the stack (pointer, length, capacity)
    // The actual

 is on the heap

    // ---- Visual representation ----
    // Stack: [x: 5] [y: true] [z: 'a'] [tuple] [s: ptr->heap]
    // Heap:  [h] [e] [l] [l] [o] (for String s)

    // ---- Moving from stack to heap ----
    let stack_data = 42;
    let heap_data = Box::new(stack_data);  // stack_data is copied to heap
    println!("Heap data: {}", heap_data);

    // ---- Moving from heap to stack (not directly) ----
    // You can't move from heap to stack without copying
    let heap_string = String::from("hello");
    // let stack_string = heap_string;  // This moves the pointer, not the data

    // ---- Stack allocation is fast ----
    // Just moves a pointer
    // ---- Heap allocation is slower ----
    // Requires finding free memory

    // ---- Stack is limited ----
    // Stack overflow if you allocate too much
    // ---- Heap is larger ----
    // You can allocate as much as the OS allows

    println!("Stack data: {}", x);
    println!("Heap data: {}", s);
}

fn main2() {
    // ---- Box: heap allocation ----
    let boxed_int = Box::new(42);
    let boxed_string = Box::new(String::from("hello"));

    println!("boxed_int: {}", boxed_int);
    println!("boxed_string: {}", boxed_string);

    // ---- Box allows recursive types ----
    // Example: linked list (not shown here)

    // ---- Box ownership ----
    let b = Box::new(5);
    // b owns the heap memory
    // When b goes out of scope, the memory is freed
}

fn main3() {
    // ---- The stack is fast ----
    // Example: stack allocation of an array
    let arr = [1, 2, 3, 4, 5];  // 5 * 4 bytes = 20 bytes on stack

    // ---- The heap is slower but flexible ----
    // Example: heap allocation of a Vec
    let vec = vec![1, 2, 3, 4, 5];  // Vec points to heap data

    // ---- Stack overflow ----
    // Allocating too much on the stack will cause a stack overflow
    // let big_array = [0; 1_000_000];  // May cause stack overflow

    // ---- Use heap for large data ----
    let big_vec = vec![0; 1_000_000];  // Vec stores data on heap
}

